 public static IntPtr CursorFromResource(SKBitmap bitmap,double hx,double hy){int size=bitmap.Width;byte[] top=new byte[size*size*4],bottom=new byte[top.Length],mask=new byte[((size+31)/32)*4*size];Marshal.Copy(bitmap.GetPixels(),top,0,top.Length);for(int y=0;y<size;y++){for(int x=0;x<size;x++){int k=y*size*4+x*4;int a=top[k+3];if(a>0&&a<255)for(int c=0;c<3;c++)top[k+c]=(byte)Math.Min(255,(top[k+c]*255+a/2)/a);}Buffer.BlockCopy(top,y*size*4,bottom,(size-1-y)*size*4,size*4);}int xh=(int)Math.Round(hx*size),yh=(int)Math.Round(hy*size);byte[] file=Fixtures.Cur(size,size,xh,yh,bottom,mask);byte[] res=new byte[file.Length-22+4];Buffer.BlockCopy(BitConverter.GetBytes((ushort)xh),0,res,0,2);Buffer.BlockCopy(BitConverter.GetBytes((ushort)yh),0,res,2,2);Buffer.BlockCopy(file,22,res,4,file.Length-22);var h=CreateIconFromResourceEx(res,(uint)res.Length,false,0x30000,size,size,0);if(h==IntPtr.Zero)throw new Exception("CreateIconFromResourceEx "+Marshal.GetLastWin32Error());return h;}
 public static IntPtr Cursor(SKBitmap bitmap,double hotX,double hotY){
  int w=bitmap.Width,h=bitmap.Height;Native.BMI bi=new(){Size=40,Width=w,Height=-h,Planes=1,BitCount=32};var color=CreateDIBSection(IntPtr.Zero,ref bi,0,out var pixels,IntPtr.Zero,0);var mask=CreateBitmap(w,h,1,1,new byte[((w+15)/16)*2*h]);
  try{if(color==IntPtr.Zero||mask==IntPtr.Zero)throw new Exception("Create cursor bitmaps");byte[] data=new byte[w*h*4];Marshal.Copy(bitmap.GetPixels(),data,0,data.Length);Marshal.Copy(data,0,pixels,data.Length);Native.ICONINFO info=new(){IsIcon=0,HotX=(uint)Math.Clamp((int)Math.Round(hotX*w),0,w-1),HotY=(uint)Math.Clamp((int)Math.Round(hotY*h),0,h-1),Color=color,Mask=mask};var c=CreateIconIndirect(ref info);if(c==IntPtr.Zero)throw new Exception("CreateIconIndirect "+Marshal.GetLastWin32Error());return c;}finally{if(color!=IntPtr.Zero)Native.DeleteObject(color);if(mask!=IntPtr.Zero)Native.DeleteObject(mask);}
 }
