 static readonly JsonSerializerOptions Json=new(){WriteIndented=true,IncludeFields=true};static readonly CultureInfo Inv=CultureInfo.InvariantCulture;static readonly XNamespace Inkscape="http://www.inkscape.org/namespaces/inkscape";static string root="",project="";static List<VectorCase> cases=new();static readonly List<object> results=new();
