 static string Slice(string source,string id){var d=Read(source);var rect=d.Descendants().Single(e=>e.Name.LocalName=="rect"&&(string?)e.Attribute("id")==id);double x=double.Parse((string)rect.Attribute("x")!,Inv),y=double.Parse((string)rect.Attribute("y")!,Inv),w=double.Parse((string)rect.Attribute("width")!,Inv),h=double.Parse((string)rect.Attribute("height")!,Inv);
  foreach(var a in rect.Ancestors()){string? tr=(string?)a.Attribute("transform");if(tr==null)continue;var m=Regex.Match(tr,@"^translate\(\s*([-\d.]+)[,\s]+([-\d.]+)\s*\)$");if(!m.Success)throw new Exception("Unexpected slice transform: "+tr);x+=double.Parse(m.Groups[1].Value,Inv);y+=double.Parse(m.Groups[2].Value,Inv);}
  foreach(var layer in d.Descendants().Where(e=>(string?)e.Attribute(Inkscape+"label")=="slices").ToArray())layer.Remove();d.Root!.SetAttributeValue("viewBox",$"{x.ToString(Inv)} {y.ToString(Inv)} {w.ToString(Inv)} {h.ToString(Inv)}");d.Root.SetAttributeValue("width",256);d.Root.SetAttributeValue("height",256);return d.ToString(SaveOptions.DisableFormatting);
