 static void LoadCases(){cases.Add(new("bibata-pointer",Ice(Source("bibata-pointer.svg")),55.0/256,17.0/256));foreach(int f in new[]{1,14,27,40})cases.Add(new($"bibata-wait{f:00}",Ice(Source($"bibata-wait{f:00}.svg")),0.5,0.5));cases.Add(new("nordzy-pointer",Slice(Source("nordzy-static.svg"),"left_ptr"),6.0/64,5.0/64));cases.Add(new("nordzy-wait01",Slice(Source("nordzy-spinner.svg"),"wait-01"),30.0/64,30.0/64));cases.Add(new("nordzy-progress01",Slice(Source("nordzy-spinner.svg"),"progress-01"),6.0/64,5.0/64));cases.Add(new("windows-static-arrow",File.ReadAllText(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"Cursors/arrow.svg")),1.0/32,1.0/32));}
 static string AtSize(string xml,int size){var d=Read(xml);d.Root!.SetAttributeValue("width",size);d.Root.SetAttributeValue("height",size);return d.ToString(SaveOptions.DisableFormatting);}
 static string WithoutFilters(string xml){var d=Read(xml);foreach(var e in d.Descendants().Where(e=>e.Name.LocalName=="filter").ToArray())e.Remove();foreach(var e in d.Descendants()){e.Attribute("filter")?.Remove();var style=e.Attribute("style");if(style!=null)style.Value=Regex.Replace(style.Value,@"filter\s*:[^;]+;?","");}return d.ToString(SaveOptions.DisableFormatting);}
 static SKBitmap Render(string xml,int size){using var svg=new SKSvg();using var stream=new MemoryStream(Encoding.UTF8.GetBytes(AtSize(xml,size)));if(svg.Load(stream)==null||svg.Picture==null)throw new Exception("SVG failed to load");var bmp=new SKBitmap(new SKImageInfo(size,size,SKColorType.Bgra8888,SKAlphaType.Premul));using var canvas=new SKCanvas(bmp);canvas.Clear(SKColors.Transparent);canvas.DrawPicture(svg.Picture);canvas.Flush();return bmp;}
 static void Save(SKBitmap b,string file){using var image=SKImage.FromBitmap(b);using var data=image.Encode(SKEncodedImageFormat.Png,100);using var output=File.Create(file);data.SaveTo(output);}
 static SKBitmap White(SKBitmap b){var r=new SKBitmap(b.Width,b.Height,SKColorType.Bgra8888,SKAlphaType.Premul);using var c=new SKCanvas(r);c.Clear(SKColors.White);c.DrawBitmap(b,0,0);return r;}
 static object Difference(SKBitmap a,SKBitmap b,int bx=0,int by=0){double abs=0,sq=0;int over=0;for(int y=0;y<a.Height;y++)for(int x=0;x<a.Width;x++){var c=a.GetPixel(x,y);var d=b.GetPixel(x+bx,y+by);int max=0;foreach(int delta in new[]{Math.Abs(c.Red-d.Red),Math.Abs(c.Green-d.Green),Math.Abs(c.Blue-d.Blue)}){abs+=delta;sq+=(double)delta*delta;max=Math.Max(max,delta);}if(max>12)over++;}double n=a.Width*(double)a.Height;return new{MeanAbsChannel=abs/n/3,RmsChannel=Math.Sqrt(sq/n/3),PixelsOver12=over,PercentPixelsOver12=100*over/n};}
 static object AlphaBytes(IntPtr cursor,SKBitmap bitmap){Native.GetIconInfo(cursor,out var i);var dc=Native.GetDC(IntPtr.Zero);try{int w=bitmap.Width,h=bitmap.Height;byte[] actual=new byte[w*h*4],src=new byte[w*h*4];Marshal.Copy(bitmap.GetPixels(),src,0,src.Length);Native.BMI bi=new(){Size=40,Width=w,Height=-h,Planes=1,BitCount=32};int lines=Native.GetDIBits(dc,i.Color,0,(uint)h,actual,ref bi,0);long diff=0;int srcPartial=0,dstPartial=0;for(int k=3;k<src.Length;k+=4){diff+=Math.Abs(src[k]-actual[k]);if(src[k]>0&&src[k]<255)srcPartial++;if(actual[k]>0&&actual[k]<255)dstPartial++;}return new{Lines=lines,SourcePartialAlpha=srcPartial,NativePartialAlpha=dstPartial,MeanAlphaDifference=diff/(double)(w*h)};}finally{Native.ReleaseDC(IntPtr.Zero,dc);Native.DeleteObject(i.Color);Native.DeleteObject(i.Mask);}}
 static SKBitmap DrawNativeWhite(IntPtr cursor,int size){Native.BMI bi=new(){Size=40,Width=size,Height=-size,Planes=1,BitCount=32};var dib=Win.CreateDIBSection(IntPtr.Zero,ref bi,0,out var bits,IntPtr.Zero,0);var dc=Win.CreateCompatibleDC(IntPtr.Zero);var previous=Win.SelectObject(dc,dib);try{byte[] bytes=Enumerable.Repeat((byte)255,size*size*4).ToArray();Marshal.Copy(bytes,0,bits,bytes.Length);if(!Native.DrawIconEx(dc,0,0,cursor,size,size,0,IntPtr.Zero,3))throw new Exception("DrawIconEx DIB");Marshal.Copy(bits,bytes,0,bytes.Length);for(int k=3;k<bytes.Length;k+=4)bytes[k]=255;var result=new SKBitmap(size,size,SKColorType.Bgra8888,SKAlphaType.Premul);Marshal.Copy(bytes,0,result.GetPixels(),bytes.Length);return result;}finally{Win.SelectObject(dc,previous);Win.DeleteDC(dc);Native.DeleteObject(dib);}}
 static object Roundtrip(VectorCase c,SKBitmap bitmap,bool resource=false){var h=resource?Win.CursorFromResource(bitmap,c.HotX,c.HotY):Win.Cursor(bitmap,c.HotX,c.HotY);try{var d=Native.Dimensions(h);using var expected=White(bitmap);using var actual=DrawNativeWhite(h,bitmap.Width);if(bitmap.Width==512)Save(actual,Path.Combine(root,c.Name+(resource?"-resource-native512.png":"-native512.png")));return new{ResourceWidth=d.W,ResourceHeight=d.H,HotX=d.X,HotY=d.Y,Alpha=AlphaBytes(h,bitmap),Difference=Difference(expected,actual)};}finally{Native.DestroyCursor(h);}}
 static void RenderAndCompare(){Directory.CreateDirectory(root);var renderTests=new List<object>();int cell=256,step=284;using var sheet=new SKBitmap(1024,852,SKColorType.Bgra8888,SKAlphaType.Premul);using var sheetCanvas=new SKCanvas(sheet);sheetCanvas.Clear(SKColors.White);var html=new StringBuilder("<!doctype html><html><head><meta charset='utf-8'><style>html,body{margin:0;background:white;width:1024px;height:852px}body{display:grid;grid-template-columns:repeat(4,256px);grid-auto-rows:284px}img{display:block;width:256px;height:256px}.label{font:14px Segoe UI;color:#222}</style></head><body>");
  for(int i=0;i<cases.Count;i++){var c=cases[i];string svgPath=Path.Combine(root,c.Name+".svg");File.WriteAllText(svgPath,AtSize(c.Xml,256));html.Append($"<div><img src='{new Uri(svgPath).AbsoluteUri}'><span class='label'>{c.Name}</span></div>");
   var metrics=new List<object>();foreach(int size in new[]{64,256,512,1024,2048}){var times=new List<double>();using(var warm=Render(c.Xml,size)){}SKBitmap? last=null;for(int n=0;n<3;n++){last?.Dispose();var sw=Stopwatch.StartNew();last=Render(c.Xml,size);times.Add(sw.Elapsed.TotalMilliseconds);}using(last){if(last==null)throw new Exception("No bitmap");int alpha=0;for(int y=0;y<size;y+=Math.Max(1,size/64))for(int x=0;x<size;x+=Math.Max(1,size/64))if(last.GetPixel(x,y).Alpha!=0)alpha++;if(alpha==0)throw new Exception("Empty render "+c.Name);var rt=Roundtrip(c,last,true);metrics.Add(new{Size=size,MeanRenderMs=times.Average(),MinRenderMs=times.Min(),MaxRenderMs=times.Max(),NonzeroAlphaSamplePoints=alpha,NativeRoundtrip=rt});if(size==256){Save(last,Path.Combine(root,c.Name+".png"));using var white=White(last);sheetCanvas.DrawBitmap(white,i%4*cell,i/4*step);}if(size==512)Save(last,Path.Combine(root,c.Name+"-512.png"));}}
   renderTests.Add(new{Name=c.Name,Sizes=metrics});}
  html.Append("</body></html>");File.WriteAllText(Path.Combine(root,"reference.html"),html.ToString());sheetCanvas.Flush();Save(sheet,Path.Combine(root,"skia-sheet.png"));results.Add(new{Name="vector-raster-and-native-roundtrip",Cases=renderTests});
  var psi=new ProcessStartInfo("D:/Program Files/Google/Chrome/Application/chrome.exe"){UseShellExecute=false,CreateNoWindow=true};foreach(var a in new[]{"--headless=new","--disable-gpu","--hide-scrollbars","--no-first-run","--no-default-browser-check","--force-device-scale-factor=1","--window-size=1280,1100","--user-data-dir="+Path.Combine(root,"edge-profile"),"--screenshot="+Path.Combine(root,"chromium-reference.png"),new Uri(Path.Combine(root,"reference.html")).AbsoluteUri})psi.ArgumentList.Add(a);using var browser=Process.Start(psi)??throw new Exception("Reference browser");if(!browser.WaitForExit(45000))throw new Exception("Reference browser timed out");var referenceWait=Stopwatch.StartNew();while(!File.Exists(Path.Combine(root,"chromium-reference.png"))&&referenceWait.ElapsedMilliseconds<15000)Thread.Sleep(100);if(!File.Exists(Path.Combine(root,"chromium-reference.png")))throw new Exception("No reference image");Thread.Sleep(300);using var reference=SKBitmap.Decode(Path.Combine(root,"chromium-reference.png"));var diffs=new List<object>();for(int i=0;i<cases.Count;i++){using var own=SKBitmap.Decode(Path.Combine(root,cases[i].Name+".png"));using var white=White(own);using var noFilter=Render(WithoutFilters(cases[i].Xml),256);using var noFilterWhite=White(noFilter);diffs.Add(new{Name=cases[i].Name,WithFilters=Difference(white,reference,i%4*cell,i/4*step),WithoutFilters=Difference(noFilterWhite,reference,i%4*cell,i/4*step)});}results.Add(new{Name="independent-chromium-comparison",ReferenceWidth=reference.Width,ReferenceHeight=reference.Height,Cases=diffs});
 }
 static void RetainedPictures(){var rows=new List<object>();foreach(var c in cases){using var svg=new SKSvg();using var src=new MemoryStream(Encoding.UTF8.GetBytes(AtSize(c.Xml,256)));svg.Load(src);if(svg.Picture==null)throw new Exception("Retained load failed");foreach(int size in new[]{256,512,1024,2048}){var times=new List<double>();SKBitmap? last=null;for(int n=0;n<4;n++){last?.Dispose();var sw=Stopwatch.StartNew();last=new SKBitmap(size,size,SKColorType.Bgra8888,SKAlphaType.Premul);using(var canvas=new SKCanvas(last)){canvas.Clear(SKColors.Transparent);canvas.Scale(size/256f);canvas.DrawPicture(svg.Picture);canvas.Flush();}if(n>0)times.Add(sw.Elapsed.TotalMilliseconds);}using(last){using var fresh=Render(c.Xml,size);using var fw=White(fresh);using var rw=White(last!);rows.Add(new{Name=c.Name,Size=size,MeanRasterOnlyMs=times.Average(),DifferenceFromFresh=Difference(fw,rw)});if(c.Name=="bibata-wait01"&&size==1024)Save(last!,Path.Combine(root,"retained-bibata-wait1024.png"));}}}results.Add(new{Name="retained-vector-picture-at-final-size",Cases=rows});
