 [STAThread]static int Main(string[] args){try{if(args[0]=="--restore-native")return NativeRestoreWatch(args);project=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../.."));root=Path.GetFullPath(args[0]);if(args.Length>1&&args[1]=="native-bench")return RunNativeBench();if(Directory.Exists(root)&&Directory.EnumerateFileSystemEntries(root).Any())throw new Exception("Run directory must be new or empty");Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);LoadCases();if(args.Length>1&&args[1]=="alpha"){Directory.CreateDirectory(root);foreach(var c in cases.Where(c=>c.Name is "bibata-pointer" or "bibata-wait01")){using var b=Render(c.Xml,512);results.Add(new{Name=c.Name,NativeIndirect=Roundtrip(c,b),NativeResource=Roundtrip(c,b,true)});}}else{RenderAndCompare();RetainedPictures();}File.WriteAllText(Path.Combine(root,"report.json"),JsonSerializer.Serialize(new{Experiment="SVG rasterization and native cursor creation, not application",Date=DateTimeOffset.Now,Renderer="Svg.Skia 5.2.3",Cases=results,NoSystemCursorMutation=true},Json));Console.WriteLine("Render and native roundtrip completed: "+Path.Combine(root,"report.json"));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
